        "reports": [
          {
            "id": "favorable",
            "label": "Favorable preference signal",
            "kind": "report"
          },
          {
            "id": "unfavorable",
            "label": "Unfavorable preference signal",
            "kind": "report"
          },
          {
            "id": "inconclusive",
            "label": "No usable preference signal",
            "kind": "no-report"
          }
        ]
      }
    ],
    "presentation": {
      "labels": {
        "baseline": "Choose a growth arrangement now",
        "study": "Learning option",
        "action": "Complete growth arrangement",
        "state": "Customer-response situation",
        "report": "Preference-test signal"
      },
      "reports": {
        "comparison": {
          "title": "Test before committing",
          "question": "Does the preference test improve expected contribution while retaining a complete usable response?"
        },
        "responses": {
          "title": "Response to each signal",
          "question": "Which eligible growth arrangement has the highest expected contribution after each possible signal?"
        },
        "inputs": {
          "title": "Probability and operating basis",
          "question": "Which explicit assumptions and complete operating assessments support this comparison?"
        }
      }
    },
    "recordTypes": []
  },
